<?php
namespace App\Livewire;
use App\Models\SchoolClass;use App\Models\Student;use App\Models\Term;use App\Services\StageTermReportCalculator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class BulkTermReports extends Component {public string $termId='',$classId='';public function mount():void{$s=Auth::user()->school;$this->termId=(string)$s->currentTerm()?->id;$this->classId=(string)SchoolClass::where('school_id',$s->id)->orderBy('sort_order')->value('id');}public function render(){$school=Auth::user()->school;$term=Term::where('school_id',$school->id)->find($this->termId);$students=$term&&$this->classId?Student::with(['schoolClass','guardians'])->where('school_id',$school->id)->where('status','active')->where(function(Builder $query){$query->whereHas('enrolments',fn(Builder $e)=>$e->where('term_id',$this->termId)->where('school_class_id',$this->classId))->orWhere(fn(Builder $fallback)=>$fallback->whereDoesntHave('enrolments',fn(Builder $e)=>$e->where('term_id',$this->termId))->where('school_class_id',$this->classId));})->orderBy('name')->get():collect();$reports=$term?$students->map(fn($student)=>['student'=>$student,'data'=>StageTermReportCalculator::student($student,$term)]):collect();$ranked=$reports->filter(fn($report)=>$report['data']['marks']->isNotEmpty())->sortByDesc('data.average')->values();$positions=[];$lastAverage=null;$position=0;foreach($ranked as$index=>$report){$average=$report['data']['average'];if($lastAverage===null||abs($average-$lastAverage)>=0.001)$position=$index+1;$positions[$report['student']->id]=$position;$lastAverage=$average;}return view('livewire.bulk-term-reports-v2',['terms'=>Term::where('school_id',$school->id)->latest('year')->get(),'classes'=>SchoolClass::where('school_id',$school->id)->orderBy('sort_order')->orderBy('name')->get(),'term'=>$term,'reports'=>$reports,'positions'=>$positions,'school'=>$school,'pageTitle'=>'Bulk Term Reports']);}}
